create or replace function private.mark_estimate_sent(p_estimate_id uuid,p_follow_up_at timestamptz default null) returns void language plpgsql security definer set search_path='' as $$ begin if not public.has_permission_for_current_user('manage_estimates') then raise exception 'Estimate permission required'; end if; update public.estimates set status='sent',sent_at=now(),expires_at=coalesce(expires_at,now()+interval '30 days'),follow_up_at=coalesce(p_follow_up_at,now()+interval '2 days') where id=p_estimate_id and status='draft'; if not found then raise exception 'Estimate is not an eligible draft'; end if; end $$;
create or replace function public.mark_estimate_sent(p_estimate_id uuid,p_follow_up_at timestamptz default null) returns void language sql set search_path='' as $$ select private.mark_estimate_sent(p_estimate_id,p_follow_up_at) $$; revoke all on function public.mark_estimate_sent(uuid,timestamptz) from public,anon; grant execute on function public.mark_estimate_sent(uuid,timestamptz) to authenticated;
create or replace function private.mark_estimate_declined(p_estimate_id uuid,p_reason text) returns void language plpgsql security definer set search_path='' as $$ begin if not public.has_permission_for_current_user('manage_estimates') then raise exception 'Estimate permission required'; end if; if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Decline reason required'; end if; update public.estimates set status='declined',declined_at=now(),decline_reason=left(trim(p_reason),1000),follow_up_at=null where id=p_estimate_id and status in ('draft','sent'); if not found then raise exception 'Estimate cannot be declined'; end if; end $$;
create or replace function public.mark_estimate_declined(p_estimate_id uuid,p_reason text) returns void language sql set search_path='' as $$ select private.mark_estimate_declined(p_estimate_id,p_reason) $$; revoke all on function public.mark_estimate_declined(uuid,text) from public,anon; grant execute on function public.mark_estimate_declined(uuid,text) to authenticated;
create or replace function private.schedule_estimate_follow_up(p_estimate_id uuid,p_follow_up_at timestamptz) returns void language plpgsql security definer set search_path='' as $$ begin if not public.has_permission_for_current_user('manage_estimates') then raise exception 'Estimate permission required'; end if; if p_follow_up_at is null then raise exception 'Follow-up time required'; end if; update public.estimates set follow_up_at=p_follow_up_at where id=p_estimate_id and status in ('draft','sent'); if not found then raise exception 'Estimate is not open'; end if; end $$;
create or replace function public.schedule_estimate_follow_up(p_estimate_id uuid,p_follow_up_at timestamptz) returns void language sql set search_path='' as $$ select private.schedule_estimate_follow_up(p_estimate_id,p_follow_up_at) $$; revoke all on function public.schedule_estimate_follow_up(uuid,timestamptz) from public,anon; grant execute on function public.schedule_estimate_follow_up(uuid,timestamptz) to authenticated;